using namespace std;

char get_grade(int score) {
    if (score >= 90) return 'A';
    else if (score >= 80) return 'B';
    else if (score >= 70) return 'C';
    else if (score >= 60) return 'D';
    else return 'F';
}

int main() {
    int scores[] = {95, 82, 71, 65, 55};
    int n = 5;

    for (int i = 0; i < n; i++) {
        char grade = get_grade(scores[i]);
        cout << grade << endl;
    }

    return 0;
}

